    /**
 * <div id="mongodb-driver-readpreference.getmodestring" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ReadPreference::getModeString</h1>  <p class="verinfo">(mongodb &gt;=1.7.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ReadPreference::getModeString</span> — <span class="dc-title">Returns the ReadPreference's "mode" option</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-readpreference.getmodestring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ReadPreference::getModeString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-readpreference.getmodestring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-readpreference.getmodestring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the ReadPreference's "mode" option as a string.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-readpreference.getmodestring-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-readpreference.getmodestring-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadPreference::getModeString()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">PRIMARY</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModeString</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">PRIMARY_PREFERRED</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModeString</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">SECONDARY</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModeString</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">SECONDARY_PREFERRED</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModeString</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">NEAREST</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModeString</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(7)&nbsp;"primary"<br>string(16)&nbsp;"primaryPreferred"<br>string(9)&nbsp;"secondary"<br>string(18)&nbsp;"secondaryPreferred"<br>string(7)&nbsp;"nearest"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-readpreference.getmodestring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\ReadPreference::getMode()} - Returns the ReadPreference's "mode" option</span></li>   <li><a href="https://www.mongodb.com/docs/manual/core/read-preference/" class="link external">»&nbsp;Read Preference reference</a></li>  </ul> </div></div>
