    /**
 * <div id="mongodb-driver-readpreference.gettagsets" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ReadPreference::getTagSets</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ReadPreference::getTagSets</span> — <span class="dc-title">Returns the ReadPreference's "tagSets" option</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-readpreference.gettagsets-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ReadPreference::getTagSets</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-readpreference.gettagsets-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-readpreference.gettagsets-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the ReadPreference's "tagSets" option.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-readpreference.gettagsets-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-readpreference.gettagsets-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadPreference::getTagSets()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$mode </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">SECONDARY_PREFERRED</span><span style="color: #007700">;<br><br></span><span style="color: #FF8000">// Null and an empty array both denote no tag set preference. <br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">\$mode</span><span style="color: #007700">, </span><span style="color: #9876AA">null</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTagSets</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">\$mode</span><span style="color: #007700">, []);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTagSets</span><span style="color: #007700">());<br><br></span><span style="color: #FF8000">// Prefer a node in New York, but fall back to any available node. <br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">\$mode</span><span style="color: #007700">, [[</span><span style="color: #DD0000">'dc' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'ny'</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTagSets</span><span style="color: #007700">());<br><br></span><span style="color: #FF8000">// Prefer a node in the New York, followed by a node in San Francisco that is<br>   labeled for reporting usage, and finally fall back to any available node. <br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">\$mode</span><span style="color: #007700">, [<br>  [</span><span style="color: #DD0000">'dc' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'ny'</span><span style="color: #007700">],<br>  [</span><span style="color: #DD0000">'dc' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'sf'</span><span style="color: #007700">, </span><span style="color: #DD0000">'use' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'reporting'</span><span style="color: #007700">],<br>  [],<br>]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTagSets</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(0)&nbsp;{<br>}<br>array(0)&nbsp;{<br>}<br>array(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["dc"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(2)&nbsp;"ny"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;array(0)&nbsp;{<br>&nbsp;&nbsp;}<br>}<br>array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["dc"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(2)&nbsp;"ny"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;array(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["dc"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(2)&nbsp;"sf"<br>&nbsp;&nbsp;&nbsp;&nbsp;["use"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(9)&nbsp;"reporting"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;array(0)&nbsp;{<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-readpreference.gettagsets-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/core/read-preference/" class="link external">»&nbsp;Read Preference reference</a></li>  </ul> </div></div>
 * 
     * Returns the ReadPreference's "tagSets" option
     * @link https://php.net/manual/zh/mongodb-driver-readpreference.gettagsets.php
     */
    final public function getTagSets(): array {}

    /**
 * <div id="mongodb-driver-readpreference.bsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\ReadPreference::bsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\ReadPreference::bsonSerialize</span> — <span class="dc-title">Returns an object for BSON serialization</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-readpreference.bsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\ReadPreference::bsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-readpreference.bsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-readpreference.bsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an object for serializing the ReadPreference as BSON.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-readpreference.bsonserialize-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-readpreference.bsonserialize-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadPreference::bsonSerialize()</strong></span> with primary read preference</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">PRIMARY</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">());<br><br>echo </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(stdClass)#2&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["mode"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"primary"<br>}<br><br>{&nbsp;"mode"&nbsp;:&nbsp;"primary"&nbsp;}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadPreference::bsonSerialize()</strong></span> with secondary read preference and tag sets</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">::</span><span style="color: #9876AA">SECONDARY</span><span style="color: #007700">,<br>    [<br>        [</span><span style="color: #DD0000">'dc' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'ny'</span><span style="color: #007700">],<br>        [</span><span style="color: #DD0000">'dc' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'sf'</span><span style="color: #007700">, </span><span style="color: #DD0000">'use' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'reporting'</span><span style="color: #007700">],<br>        []<br>    ]<br>);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">());<br><br>echo </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(stdClass)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["mode"]=&gt;<br>&nbsp;&nbsp;string(9)&nbsp;"secondary"<br>&nbsp;&nbsp;["tags"]=&gt;<br>&nbsp;&nbsp;array(3)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(stdClass)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["dc"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(2)&nbsp;"ny"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(stdClass)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["dc"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(2)&nbsp;"sf"<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["use"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(9)&nbsp;"reporting"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(stdClass)#4&nbsp;(0)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;}<br>}<br><br>{&nbsp;"mode"&nbsp;:&nbsp;"secondary",&nbsp;"tags"&nbsp;:&nbsp;[&nbsp;{&nbsp;"dc"&nbsp;:&nbsp;"ny"&nbsp;},&nbsp;{&nbsp;"dc"&nbsp;:&nbsp;"sf",&nbsp;"use"&nbsp;:&nbsp;"reporting"&nbsp;},&nbsp;{&nbsp;&nbsp;}&nbsp;]&nbsp;}</blockquote></div>   </div>  </div>  <div class="example" id="example-3">   <p><strong>示例 #3 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\ReadPreference::bsonSerialize()</strong></span> with secondary read preference and max staleness</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\